    germany1845: [[1919, 'The Weimar Constitution; the Spartacist Rising'], [1923, 'Hyperinflation; the Ruhr; the Munich Putsch'], [1924, 'The Dawes Plan'], [1925, 'The Locarno Treaties'], [1929, 'Stresemann dies; the Wall Street Crash'], [1933, 'Hitler Chancellor; Reichstag Fire; Enabling Act'], [1934, 'Night of the Long Knives; Hindenburg dies'], [1935, 'The Nuremberg Laws'], [1938, 'Kristallnacht'], [1942, 'The Wannsee Conference plans the "Final Solution"']],
    russia: [[1905, 'Bloody Sunday; the October Manifesto'], [1906, 'The first Duma meets; Stolypin\'s reforms begin'], [1915, 'The Tsar takes personal command of the army'], [1917, 'The March Revolution; the Bolsheviks seize power in November'], [1918, 'The Treaty of Brest-Litovsk; the Civil War begins'], [1921, 'The Kronstadt Rising; the NEP introduced'], [1924, 'Lenin dies'], [1928, 'The first Five-Year Plan begins'], [1934, 'Kirov is murdered'], [1936, 'The first great show trial']],
